.ds-notebook{position:relative;isolation:isolate;margin:1rem 8px 0;font-family:var(--font-body,"Plus Jakarta Sans","Helvetica Neue",Arial,sans-serif);color:var(--ink,#20221f)}.ds-notebook::before,.ds-notebook::after{content:"";position:absolute;inset:0 0 3.5rem;border-radius:var(--radius-card,28px);transform-origin:50% 75%;z-index:-1}.ds-notebook::before{background:var(--surface-accent-strong,color-mix(in srgb,var(--cobalt,#245bff) 14%,var(--surface-raised,#fffefa) 86%));transform:translate(6px,-14px) rotate(-4deg);z-index:-2}.ds-notebook::after{background:var(--surface-accent,color-mix(in srgb,var(--cobalt,#245bff) 6%,var(--surface-raised,#fffefa) 94%));transform:translate(3px,-7px) rotate(3deg)}.ds-notebook-front{display:flex;flex-direction:column;gap:1rem;padding:clamp(1.25rem,3vw,1.75rem);border-radius:var(--radius-card,28px);background:var(--surface-raised,#fffefa);box-shadow:var(--shadow-card,0 8px 16px rgb(32 34 31 / .035),0 28px 54px -20px rgb(32 34 31 / .15));overflow-wrap:anywhere}.ds-notebook h3{max-width:26ch;margin:0;font-size:clamp(1.25rem,1.8vw,1.5rem);font-weight:500;line-height:1.4;letter-spacing:-.03em;text-wrap:balance}.ds-notebook-answer{display:grid;overflow:clip}.ds-notebook-answer p{grid-area:1/1;max-width:36ch;margin:0;color:var(--muted,#62625e);font-size:1rem;line-height:1.65}.ds-notebook-answer p[hidden]{display:none}.ds-notebook button{display:inline-flex;align-items:center;justify-content:flex-start;min-height:44px;padding:.5rem 0;border:0;background:none;color:var(--action-ink,#245bff);font:inherit;font-size:.9375rem;line-height:1.5;cursor:pointer}.ds-notebook-reveal{align-self:flex-start}.ds-notebook-button-visual{display:inline-flex;text-decoration:underline;text-underline-offset:.25em}.ds-notebook button:hover .ds-notebook-button-visual{text-decoration-thickness:2px}.ds-notebook button:focus-visible{outline:2px solid var(--cobalt,#245bff);outline-offset:4px}.ds-notebook button:active:not(:focus-visible):not(:disabled) .ds-notebook-button-visual{transform:scale(.97)}.ds-notebook button:focus-visible .ds-notebook-button-visual,.ds-notebook button:disabled .ds-notebook-button-visual{transform:none}.ds-notebook-footer{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:.25rem 1rem;margin-top:.75rem;padding-inline:8px}.ds-notebook-footer>span{color:var(--muted,#62625e);font-size:.75rem;line-height:1.5}.ds-notebook .ds-notebook-next{font-size:.8125rem}@media(prefers-reduced-motion:reduce),(forced-colors:active){.ds-notebook::before,.ds-notebook::after{display:none}.ds-notebook-button-visual{transform:none!important}}@media(forced-colors:active){.ds-notebook-front{border:1px solid CanvasText;background:Canvas;box-shadow:none}.ds-notebook button{color:LinkText}}
.ds-notebook{overflow:visible;container-type:inline-size}.ds-notebook-discoveries{display:inline-flex;gap:.3rem}.ds-notebook-discoveries>span{width:15px;height:15px;border-radius:50%;background:var(--surface-accent-strong)}@container(max-width:18rem){.ds-notebook::after{transform:translate(3px,-7px) rotate(1deg)}.ds-notebook::before{transform:translate(6px,-14px) rotate(-1.5deg)}}
.ds-notebook-progress{display:flex;flex-wrap:wrap;align-items:center;gap:.75rem;color:var(--muted);font-size:.75rem;line-height:1.5}
.ds-notebook{width:100%;max-width:460px;margin:0;padding:1rem 8px 0}.ds-notebook-front{gap:.75rem}.ds-notebook-footer{padding-inline:0}.ds-notebook::before,.ds-notebook::after{inset:1rem 8px 3.5rem}

.ds-demo-experiment { display: flex; flex-wrap: wrap; align-items: center; gap: 1.5rem; width: calc(100% - 16px); max-inline-size: 480px; min-width: 0; justify-self: start; margin-inline: 8px; padding: clamp(1.25rem, 2vw, 1.75rem); border-radius: var(--radius-card); background: var(--surface-raised); box-shadow: var(--shadow-card); overflow-wrap: break-word; }
.ds-demo-experimentControls { flex: 1 1 11rem; min-width: 0; }
.ds-demo-experiment h3 { max-width: 26ch; font-size: clamp(1.25rem, 1.8vw, 1.5rem); font-weight: 500; line-height: 1.4; letter-spacing: -.03em; text-wrap: balance; }
.ds-demo-motionModes { display: inline-flex; flex-wrap: wrap; max-inline-size: 100%; gap: .25rem; margin-block-start: 1rem; padding: .25rem; border-radius: var(--radius-pill); background: var(--surface); }
.ds-demo-motionModes button { min-width: 72px; min-height: 44px; padding: .5rem 1rem; border: 0; border-radius: var(--radius-pill); background: transparent; color: var(--muted); font-size: .875rem; line-height: 1.5; cursor: pointer; }
.ds-demo-motionModes button[aria-pressed="true"] { background: var(--surface-accent); color: var(--action-ink); text-decoration: underline; text-underline-offset: .25em; }
.ds-demo-saveButton { display: block; position: relative; flex: 0 1 9.75rem; max-inline-size: 100%; inline-size: min(9.75rem, 100%); min-block-size: 9.75rem; margin-inline: auto; padding: 0; border: 0; border-radius: var(--radius-pill); background: transparent; color: var(--on-accent); cursor: pointer; }
.ds-demo-savePaint { width: 100%; min-block-size: inherit; display: flex; flex-direction: column; justify-content: center; align-items: center; gap: .75rem; padding: 1rem; border-radius: inherit; background: var(--accent-solid); box-shadow: var(--shadow-control); font-size: .875rem; font-weight: 500; line-height: 1.5; }
.ds-demo-saveButton[data-saved] { color: var(--ink); }
.ds-demo-saveButton[data-saved] .ds-demo-saveIcon { color: var(--action-ink); }
.ds-demo-saveButton[data-saved] .ds-demo-savePaint { background: var(--surface-accent-strong); }
.ds-demo-saveIcon { position: relative; width: 28px; height: 28px; }
.ds-demo-saveIcon > span { position: absolute; inset: 0; display: grid; place-items: center; }
.ds-demo-motionModes button:focus-visible, .ds-demo-saveButton:focus-visible { outline: 2px solid var(--cobalt); outline-offset: 4px; }
.ds-demo-srOnly { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; }
@media (hover: hover) and (pointer: fine) { .ds-demo-motionModes button:hover { color: var(--ink); } }
@media (forced-colors: active) { .ds-demo-experiment { border: 1px solid CanvasText; box-shadow: none; } .ds-demo-motionModes button[aria-pressed="true"] { outline: 1px solid Highlight; } .ds-demo-savePaint { background: ButtonFace; color: ButtonText; border: 1px solid ButtonText; box-shadow: none; } .ds-demo-saveButton[data-saved] .ds-demo-savePaint { background: Highlight; color: HighlightText; } }
@media print { .ds-demo-experiment { display: none; } }

.ds-demo-experiment{font-family:var(--font-body,"Plus Jakarta Sans","Helvetica Neue",Arial,sans-serif);color:var(--ink)}.ds-demo-experiment h3{margin:0}
